	} else if (command === 'trust:ingest') {
		const result = await ingestTrustInputs({
			allowNetwork: args.includes('--allow-network'),
			consentId: valueAfter('--consent-id'),
		});
		console.log(
			JSON.stringify({
				result: 'ingested',
				purpose: result.purpose,
				consentId: result.consent.consentId,
				packages: result.packages.length,
			}),
		);
	} else if (command === 'trust:generate') {
		const policyPath = valueAfter('--policy');
		const outputDir = valueAfter('--output');
		if (!policyPath || !outputDir)
			throw new Error('trust:generate requires --policy and --output');
		console.log(
			JSON.stringify(
				await generateTrustPackage({
					offline: args.includes('--offline'),
					policyPath,
					outputDir,
				}),
			),
		);
	} else if (command === 'report:enterprise') {
		// The operator-facing flow an enterprise reviewer is handed: it verifies the
		// trust package first, then re-derives the one machine artifact and the one
		// human document from the same canonical receipts. `--verify-only` refuses
		// to write, so a reviewer can check the published pair without touching it.
		const outputDir = valueAfter('--output') ?? 'evidence/trust/current';
		if (!args.includes('--offline')) throw new Error('report:enterprise requires --offline');
		const verifyOnly = args.includes('--verify-only');
		const result = await runEnterpriseReport({
			outputDir,
			verifyOnly,
			environment: { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' },
		});
		console.log(JSON.stringify(result));
	} else if (command === 'trust:verify') {
		const outputDir = args.find((arg) => !arg.startsWith('--'));
		console.log(
			JSON.stringify(
				await verifyTrustPackage({
					outputDir: outputDir ?? 'evidence/trust/current',
					compareDir: valueAfter('--compare'),
					environment: args.includes('--offline')
						? { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' }
						: process.env,
				}),
			),
		);
	} else throw new Error(`Unknown command: ${command}`);
} catch (error) {
	console.error(error instanceof Error ? error.stack : String(error));
	process.exitCode = 1;
}

